require __DIR__.'/app/bootstrap.php'; require_login(); require __DIR__.'/app/layout.php';
$stats=$pdo->query("SELECT (SELECT COUNT(*) FROM applicants) applicants, (SELECT COUNT(*) FROM registrations) registrations, (SELECT COUNT(*) FROM id_cards) cards, (SELECT COUNT(*) FROM id_cards WHERE status='Issued') issued")->fetch();
$recent=$pdo->query("SELECT a.id,a.applicant_no,a.first_name,a.last_name,a.status,r.registration_date FROM applicants a LEFT JOIN registrations r ON r.applicant_id=a.id ORDER BY a.created_at DESC LIMIT 6")->fetchAll();
page_header('Dashboard'); ?>
<div class="welcome"><div><h2>Hello, <?=e($_SESSION['full_name']??'Officer')?>.</h2><p>Manage registrations and National ID card issuance from one place.</p></div><a class="btn primary" href="applicant_form.php">＋ Register applicant</a></div>
<div class="stats"><article class="stat"><span class="stat-label">Applicants</span><strong><?= (int)$stats['applicants'] ?></strong><small>All applicant records</small></article><article class="stat"><span class="stat-label">Registrations</span><strong><?= (int)$stats['registrations'] ?></strong><small>Registration entries</small></article><article class="stat"><span class="stat-label">Cards recorded</span><strong><?= (int)$stats['cards'] ?></strong><small>Card issuance records</small></article><article class="stat"><span class="stat-label">Cards issued</span><strong><?= (int)$stats['issued'] ?></strong><small>Currently issued status</small></article></div>
<section class="panel"><div class="panel-heading"><div><h2>Recently registered</h2><p class="muted">Latest applicant records</p></div><a class="text-link" href="applicants.php">View all applicants →</a></div><div class="table-wrap"><table><thead><tr><th>Applicant no.</th><th>Applicant</th><th>Registration date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($recent as $a): ?><tr><td><strong><?=e($a['applicant_no'])?></strong></td><td><?=e($a['first_name'].' '.$a['last_name'])?></td><td><?=e($a['registration_date']??'Not registered')?></td><td><span class="pill"><?=e($a['status'])?></span></td><td><a href="applicant_view.php?id=<?=(int)$a['id']?>">View</a></td></tr><?php endforeach; if(!$recent): ?><tr><td colspan="5" class="empty">No applicants yet. Register your first fictional applicant.</td></tr><?php endif; ?></tbody></table></div></section>
